import json
from itertools import permutations

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3, 4]  # left to right as seen from across the street
    names = ["Peter", "Arnold", "Alice", "Eric"]
    colors = ["yellow", "green", "red", "white"]

    solutions = []

    for name_perm in permutations(names):
        # Constraint 2: Peter is in the first house.
        if name_perm[0] != "Peter":
            continue

        # Constraint 4: Arnold is directly left of Eric.
        idx_arnold = name_perm.index("Arnold")
        idx_eric = name_perm.index("Eric")
        if idx_arnold + 1 != idx_eric:
            continue

        for color_perm in permutations(colors):
            # Constraint 1: The person whose favorite color is green is in the third house.
            if color_perm[2] != "green":
                continue

            # Constraint 5: Eric is the person who loves yellow.
            if color_perm[idx_eric] != "yellow":
                continue

            # Constraint 3: One house between red and yellow.
            idx_red = color_perm.index("red")
            idx_yellow = color_perm.index("yellow")
            if abs(idx_red - idx_yellow) != 2:
                continue

            # If all constraints are satisfied, collect the solution
            assignment = []
            for i, house in enumerate(houses):
                assignment.append({
                    "House": str(house),
                    "Name": name_perm[i],
                    "favorite color": color_perm[i]
                })
            solutions.append(assignment)

    if not solutions:
        raise ValueError("No solution found with the given constraints.")

    # Assuming unique solution; take the first
    solution = solutions[0]

    # Build JSON structure
    header = ["House", "Name", "favorite color"]
    rows = [[row["House"], row["Name"], row["favorite color"]] for row in solution]

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
